#!/usr/bin/env bash
# ============================================================
#  push-fix-all.sh  –  EINE Datei: kompletten Fix pushen (Option B)
#  ------------------------------------------------------------
#  Der vollstaendige Aenderungs-Diff (Code + Content + Workflows)
#  ist am Dateiende als Base64 eingebettet (ab #__PATCH_B64__).
#
#  Ablauf (auf DEINEM Rechner, PAT bleibt bei dir):
#    1. frisches Klon von frank-hartung/franksfinanzcheck-blog
#    2. Branch arena/01a0668b-franksfinanzcheck-blog aus origin/main
#    3. kompletten Diff anwenden + als EIN Commit committen
#    4. pushen (force: der Branch enthaelt auf GitHub nur den
#       Teil-Push dieser Fixes – kein fremder Commit geht verloren)
#
#  Git fragt beim Push: Username = GitHub-Name,
#  Passwort = PAT mit Scopes: repo + workflow  (workflow ist PFLICHT!)
# ============================================================
set -euo pipefail

DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="frank-hartung/franksfinanzcheck-blog"
BRANCH="arena/01a0668b-franksfinanzcheck-blog"
WORK="$(mktemp -d "${TMPDIR:-/tmp}/ffc-push.XXXXXX")"
PATCH="$WORK/aenderungen.patch"

echo "==> Arbeitsordner: $WORK"
echo "==> Frisches Klon von $REPO …"
git clone --quiet "https://github.com/$REPO.git" "$WORK/repo"
cd "$WORK/repo"

echo "==> Branch $BRANCH aus origin/main erzeugen …"
git checkout -q -b "$BRANCH" origin/main

echo "==> Eingebetteten Diff (Base64) extrahieren …"
awk '/^#__PATCH_B64__/{f=1;next} f' "$0" | base64 -d > "$PATCH"
if [ ! -s "$PATCH" ]; then
  echo "FEHLER: Eingebetteter Patch nicht gefunden – Datei evtl. veraendert?"
  exit 1
fi

echo "==> Aenderungen anwenden …"
git apply --3way "$PATCH" || git apply "$PATCH"

git add -A
if git diff --cached --quiet; then
  echo "FEHLER: Keine Aenderungen zum Committen (Patch evtl. schon angewendet?)."
  exit 1
fi
echo "==> Committen …"
if ! git commit -q -m "fix(cadence): 2-3 LIVE an Mo/Mi/Fr dauerhaft garantieren (Ursache Mi 02.09.)

Vier-Baustein-Fix: URL-Hygiene-Heiler (fix_url_hygiene.py), LIVE-only
Engine-Tagesbilanz, Reserve-Pool (2 Premium-Artikel), Kadenz-Endkontrolle.
Siehe FIX-2-3-LIVE-Mo-Mi-Fr.md."; then
  echo ""
  echo "Git-Identitaet fehlt. Bitte EINMALIG global setzen und Skript neu starten:"
  echo "  git config --global user.name \"Dein Name\""
  echo "  git config --global user.email \"deine@example.com\""
  exit 1
fi

echo ""
echo "==> Fertig. Letzte Commits:"
git log --oneline -3
echo ""
echo "==> Pushe jetzt (force, da der Branch auf GitHub nur einen Teil-Push"
echo "     dieses Fixes enthaelt – nichts Fremdes geht verloren). Git fragt:"
echo "      Username = dein GitHub-Benutzername"
echo "      Passwort = dein PAT (Scopes: repo + workflow)"
echo ""
git push -u --force origin "$BRANCH"

echo ""
echo "✅ Push erfolgreich. Danach zeigt GitHub den Banner"
echo "   'Compare & pull request' -> PR gegen main oeffnen und mergen."
echo "   Arbeitsordner $WORK kann geloescht werden."
exit 0
